export const openingQuestion = 'What do you notice first?';
// Local prompts, not generated by a remote AI. No text leaves the browser.
export function followUpFor(answer) {
  const text = answer.toLowerCase();
  if (/\b(colou?r|blue|red|pink|green|yellow|black|white|aqua|gold|purple|ivory|cream)\b/.test(text)) return 'What about the color catches your attention?';
  if (/\b(texture|fabric|material|silk|soft|rough|surface)\b/.test(text)) return 'What makes you imagine the material feeling that way?';
  if (/\b(shape|silhouette|form|length|sleeve|neckline|volume)\b/.test(text)) return 'How does that shape affect your impression of the garment?';
  if (/\b(pleat|pleats|fold|folds|drape|draping|movement)\b/.test(text)) return 'How do you imagine those details changing when someone moves?';
  if (/\b(pattern|bead|beads|beading|motif|ornament|detail)\b/.test(text)) return 'Where does that detail lead your eye next?';
  return 'What about that caught your attention, and what does it make you wonder?';
}
